    /// </summary>
    [ArcGISMethod]
    public override async ValueTask Refresh()
    {
        await base.Refresh();
        if (CoreJsModule is null)
        {
            return;
        }
        
        try 
        {
            JsComponentReference ??= await CoreJsModule.InvokeAsync<IJSObjectReference?>(
                "getJsComponent", CancellationTokenSource.Token, Id);
        }
        catch (JSException)
        {
            // this is expected if the component is not yet built
        }
        
        if (JsComponentReference is null)
        {
            return;
        }
        
        await JsComponentReference!.InvokeVoidAsync(
            "refresh", 
            CancellationTokenSource.Token);
    }
    
#endregion

#region Event Handlers

    /// <summary>
    ///     JavaScript-Invokable Method for internal use only.
    /// </summary>
    [JSInvokable]
    public async Task OnJsRefresh(IJSStreamReference jsStreamRef)
    {
        if (IsDisposed)
        {
            // cancel if the component is disposed
            return;
        }
    
        RefreshEvent? refreshEvent = await jsStreamRef.ReadJsStreamReference<RefreshEvent>();
        if (refreshEvent is not null)
        {
            await OnRefresh.InvokeAsync(refreshEvent);
        }
    }
    
    /// <summary>
    ///     <a target="_blank" href="https://docs.geoblazor.com/pages/classes/dymaptic.GeoBlazor.Pro.Components.Layers.CatalogLayer.html#cataloglayeronrefresh-property">GeoBlazor Docs</a>
    ///     Fires if the layer has the <a href="#refreshInterval">refreshInterval</a> set or when <a href="#refresh">refresh()</a> method is called.
    ///     The event payload indicates if the layer's data has changed.
    /// </summary>
    [Parameter]
    [JsonIgnore]
    public EventCallback<RefreshEvent> OnRefresh { get; set; }
   
    /// <summary>
    ///     Used in JavaScript layer to determine if the event listener is registered.
    /// </summary>
    public bool HasRefreshListener => OnRefresh.HasDelegate;
    
#endregion


    /// <inheritdoc />
    protected override async ValueTask<bool> RegisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case DisplayFilterInfo displayFilterInfo:
                if (displayFilterInfo != DisplayFilterInfo)
                {
                    DisplayFilterInfo = displayFilterInfo;
                    ModifiedParameters[nameof(DisplayFilterInfo)] = DisplayFilterInfo;
                    if (MapRendered)
                    {
                        await UpdateLayer();
                    }
                }
                
                return true;
            case ElevationInfo elevationInfo:
                if (elevationInfo != ElevationInfo)
                {
                    ElevationInfo = elevationInfo;
                    ModifiedParameters[nameof(ElevationInfo)] = ElevationInfo;
                    if (MapRendered)
                    {
                        await UpdateLayer();
                    }
                }
                
                return true;
            case LayerFloorInfo floorInfo:
                if (floorInfo != FloorInfo)
                {
                    FloorInfo = floorInfo;
                    ModifiedParameters[nameof(FloorInfo)] = FloorInfo;
                    if (MapRendered)
                    {
                        await UpdateLayer();
                    }
                }
                
                return true;
            case OrderByInfo orderBy:
                OrderBy ??= [];
                if (!OrderBy.Contains(orderBy))
                {
                    OrderBy = [..OrderBy, orderBy];
                    ModifiedParameters[nameof(OrderBy)] = OrderBy;
                    if (MapRendered)
                    {
                        await UpdateLayer();
                    }
                }
                
                return true;
            case PortalItem portalItem:
                if (portalItem != PortalItem)
                {
                    PortalItem = portalItem;
                    ModifiedParameters[nameof(PortalItem)] = PortalItem;
                    if (MapRendered)
                    {
                        await UpdateLayer();
                    }
                }
                
                return true;
            case SpatialReference spatialReference:
                if (spatialReference != SpatialReference)
                {
                    SpatialReference = spatialReference;
                    ModifiedParameters[nameof(SpatialReference)] = SpatialReference;
                    if (MapRendered)
                    {
                        await UpdateLayer();
                    }
                }
                
                return true;
            case TimeExtent timeExtent:
                if (timeExtent != TimeExtent)
                {
                    TimeExtent = timeExtent;
                    ModifiedParameters[nameof(TimeExtent)] = TimeExtent;
                    if (MapRendered)
                    {
                        await UpdateLayer();
                    }
                }
                
                return true;
            case TimeInfo timeInfo:
                if (timeInfo != TimeInfo)
                {
                    TimeInfo = timeInfo;
                    ModifiedParameters[nameof(TimeInfo)] = TimeInfo;
                    if (MapRendered)
                    {
                        await UpdateLayer();
                    }
                }
                
                return true;
            case TimeInterval timeOffset:
                if (timeOffset != TimeOffset)
                {
                    TimeOffset = timeOffset;
                    ModifiedParameters[nameof(TimeOffset)] = TimeOffset;
                    if (MapRendered)
                    {
                        await UpdateLayer();
                    }
                }
                
                return true;
            default:
                return await base.RegisterGeneratedChildComponent(child);
        }
    }

    /// <inheritdoc />
    protected override async ValueTask<bool> UnregisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case DisplayFilterInfo _:
                DisplayFilterInfo = null;
                ModifiedParameters[nameof(DisplayFilterInfo)] = DisplayFilterInfo;
                return true;
            case ElevationInfo _:
                ElevationInfo = null;
                ModifiedParameters[nameof(ElevationInfo)] = ElevationInfo;
                return true;
            case LayerFloorInfo _:
                FloorInfo = null;
                ModifiedParameters[nameof(FloorInfo)] = FloorInfo;
                return true;
            case OrderByInfo orderBy:
                OrderBy = OrderBy?.Where(o => o != orderBy).ToList();
                ModifiedParameters[nameof(OrderBy)] = OrderBy;
                return true;
            case PortalItem _:
                PortalItem = null;
                ModifiedParameters[nameof(PortalItem)] = PortalItem;
                return true;
            case SpatialReference _:
                SpatialReference = null;
                ModifiedParameters[nameof(SpatialReference)] = SpatialReference;
                return true;
            case TimeExtent _:
                TimeExtent = null;
                ModifiedParameters[nameof(TimeExtent)] = TimeExtent;
                return true;
            case TimeInfo _:
                TimeInfo = null;
                ModifiedParameters[nameof(TimeInfo)] = TimeInfo;
                return true;
            case TimeInterval _:
                TimeOffset = null;
                ModifiedParameters[nameof(TimeOffset)] = TimeOffset;
                return true;
            default:
                return await base.UnregisterGeneratedChildComponent(child);
        }
    }
    
    /// <inheritdoc />
    public override void ValidateRequiredGeneratedChildren()
    {
    
        DisplayFilterInfo?.ValidateRequiredGeneratedChildren();
        ElevationInfo?.ValidateRequiredGeneratedChildren();
        FloorInfo?.ValidateRequiredGeneratedChildren();
        if (OrderBy is not null)
        {
            foreach (OrderByInfo child in OrderBy)
            {
                child.ValidateRequiredGeneratedChildren();
            }
        }
        PortalItem?.ValidateRequiredGeneratedChildren();
        SpatialReference?.ValidateRequiredGeneratedChildren();
        TimeExtent?.ValidateRequiredGeneratedChildren();
        TimeInfo?.ValidateRequiredGeneratedChildren();
        TimeOffset?.ValidateRequiredGeneratedChildren();
        base.ValidateRequiredGeneratedChildren();
    }
      
